void result(std::string label,const PhaseResult<std::monostate>&r){std::cout<<label<<"="<<r.success()<<":"<<unsigned(r.state)<<":"<<unsigned(r.failure);for(auto&d:r.diagnostics)std::cout<<"|"<<d.code<<":"<<d.phase<<":"<<d.severity<<":"<<d.message<<":"<<(d.primary?std::to_string(d.primary->snapshot.value)+":"+std::to_string(d.primary->begin_byte)+":"+std::to_string(d.primary->end_byte):"-");std::cout<<"\n";}
